import{a as e,i as t,n,r,t as i}from"./partMasterView-SNc7SpAe.js";import{a,c as o,d as s,i as c,l,r as u,s as d}from"./moneyDisplay-D450XuIv.js";import{c as f,d as p,l as m,s as h,u as g}from"./listPresentation-DDNuWPQd.js";import{Br as _,Ir as v,Lr as y,Rr as b,zr as x}from"./index-BJyQeJz8.js";var S=u({id:`part`,label:`Part`,labelPlural:`Parts`,collection:`parts`,readVia:`CLIENT_DIRECT`,readCapability:null,identity:a({nameField:`name`,referenceField:`internalPartNumber`}),description:`A catalog record: descriptive identity only. Stock, cost and supplier data live in other authorities.`,fields:[c({id:`partId`,entityId:`part`,label:`Part ID`,type:`ID`,description:`The Firestore document id. partFromFirestore throws if the stored partId does not match it.`}),c({id:`internalPartNumber`,entityId:`part`,defaultVisible:!0,label:`Part Number`,type:`STRING`,sortable:!0,description:`The catalog number staff use. Required on every Part; the referenceField half of identity.`}),c({id:`name`,entityId:`part`,defaultVisible:!0,label:`Name`,type:`STRING`,sortable:!0,description:`Required on every Part; the nameField half of identity.`}),c({id:`description`,entityId:`part`,label:`Description`,type:`TEXT`,unsupportedFilterReason:s.NEEDS_INDEX,unsupportedSortReason:s.NO_CANONICAL_ORDER,absence:l.NOT_RECORDED,description:`Optional.`}),c({id:`category`,entityId:`part`,label:`Category`,type:`STRING`,unsupportedFilterReason:s.NEEDS_INDEX,unsupportedSortReason:s.NO_CANONICAL_ORDER,absence:l.NOT_RECORDED,description:`Optional, free text. No canonical vocabulary exists on the domain type.`}),c({id:`status`,entityId:`part`,defaultVisible:!0,label:`Status`,type:`ENUM`,enumValues:[...r],enumLabels:b,filterable:!0,sortable:!0,operators:[`EQUALS`,`IN`]}),c({id:`stockingClass`,entityId:`part`,defaultVisible:!0,label:`Stocking Class`,type:`ENUM`,enumValues:[...t],enumLabels:x,filterable:!0,sortable:!0,operators:[`EQUALS`,`IN`],description:`STOCKED / NON_STOCK / SERVICE / KIT — what kind of catalog line this is, not how many are on hand.`}),c({id:`stockingUnit`,entityId:`part`,label:`Unit`,type:`ENUM`,enumValues:[...e],enumLabels:_,unsupportedFilterReason:s.NEEDS_INDEX,unsupportedSortReason:s.NO_CANONICAL_ORDER}),c({id:`controlType`,entityId:`part`,defaultVisible:!0,label:`Control Type`,type:`ENUM`,enumValues:[...i],enumLabels:v,unsupportedFilterReason:s.NEEDS_INDEX,unsupportedSortReason:s.NO_CANONICAL_ORDER,description:"PART MASTER's own tracking vocabulary — STANDARD / SERIALIZED / LOT / SERIALIZED_LOT. NOT the inventory ledger's `trackingMode`: partMaster/controlTypeTrackingMode.ts is the one mapping between them, and it exists because the mapping had already been copied twice. A surface showing one under the other's name is how two screens come to disagree about whether a part is counted by quantity or by serial."}),c({id:`primaryManufacturerId`,entityId:`part`,label:`Manufacturer`,type:`STRING`,description:`Stored as primaryManufacturerId; the domain type (functions/src/partMaster/types.ts) calls the same field manufacturerId. No manufacturer entity is registered in this program yet, so this stays a plain id rather than a REFERENCE this registry cannot resolve.`}),c({id:`primaryManufacturerPartNumber`,entityId:`part`,label:`Manufacturer Part Number`,type:`STRING`,unsupportedFilterReason:s.NOT_PROJECTED,unsupportedSortReason:s.NOT_PROJECTED,description:`Stored as primaryManufacturerPartNumber; the domain type calls it manufacturerPartNumber. Optional.`}),c({id:`oemStatus`,entityId:`part`,label:`OEM Status`,type:`ENUM`,enumValues:[...n],enumLabels:y,description:`Optional.`}),c({id:`wholeUnit`,entityId:`part`,label:`Item Type`,type:`BOOLEAN`,unsupportedFilterReason:s.NOT_PROJECTED,unsupportedSortReason:s.NOT_PROJECTED,description:`Written to the document ONLY when true; absent otherwise, never stored as false.`}),c({id:`equipmentModelId`,entityId:`part`,label:`Equipment Model`,type:`REFERENCE`,referenceTo:`equipmentModel`,unsupportedFilterReason:s.NOT_PROJECTED,unsupportedSortReason:s.NOT_PROJECTED,absence:l.UNRESOLVED,description:`Legal ONLY when wholeUnit is true (enforced by validatePart at the command layer, not by Rules or this metadata). The stored value is the equipment_models document id, verified canonical and checked to exist by assertEquipmentModelExists on every write — see the file header.`}),c({id:`warehouseAvailable`,entityId:`part`,label:`Warehouse Available`,type:`NUMBER`,defaultVisible:!1,unsupportedFilterReason:s.NOT_PROJECTED,unsupportedSortReason:s.NOT_PROJECTED,absence:l.UNKNOWN,description:`getPartBalance → available (onHand − reserved, ACTIVE warehouses only, EXCLUDES truck stock). Not stored on the Part; resolved per part where a balance read has already run.`}),c({id:`onOrder`,entityId:`part`,label:`On Order`,type:`NUMBER`,defaultVisible:!1,unsupportedFilterReason:s.NOT_PROJECTED,unsupportedSortReason:s.NOT_PROJECTED,absence:l.UNKNOWN,description:`getPartBalance → onOrder, the canonical outstanding inbound. This metadata consumes that projection and re-implements none of its SENT-counts / APPROVED-does-not rules.`}),c({id:`reorderPoint`,entityId:`part`,label:`Reorder Point`,type:`NUMBER`,defaultVisible:!1,unsupportedFilterReason:s.DERIVED_AT_READ,unsupportedSortReason:s.DERIVED_AT_READ,absence:l.UNKNOWN,description:`Calculated from usage, NOT stored on the Part.`}),c({id:`unitCost`,entityId:`part`,label:`Unit Cost`,type:`CURRENCY_MINOR`,displayable:!1,reportable:!1,exportable:!1,unsupportedFilterReason:s.NO_AUTHORITY,unsupportedSortReason:s.NO_AUTHORITY,description:`BLOCKED — the canonical Part carries no cost of any kind. See PART_INVENTORY_VALUATION_AUTHORITY_GAP.`}),c({id:`sellPrice`,entityId:`part`,label:`Sell Price`,type:`CURRENCY_MINOR`,displayable:!1,reportable:!1,exportable:!1,unsupportedFilterReason:s.NO_AUTHORITY,unsupportedSortReason:s.NO_AUTHORITY,description:`BLOCKED — no sell or list price exists on the Part.`}),c({id:`businessLine`,entityId:`part`,label:`Business Line`,type:`STRING`,displayable:!1,reportable:!1,exportable:!1,unsupportedFilterReason:s.NO_AUTHORITY,unsupportedSortReason:s.NO_AUTHORITY,description:`BLOCKED — the Part carries no operating company. See PART_BUSINESS_LINE_NOT_AUTHORITATIVE.`}),c({id:`mobileQuantity`,entityId:`part`,label:`Truck Stock`,type:`NUMBER`,displayable:!1,reportable:!1,exportable:!1,unsupportedFilterReason:s.NO_AUTHORITY,unsupportedSortReason:s.NO_AUTHORITY,description:`BLOCKED — onHand is warehouse-only by design and no mobile figure is projected. Showing warehouse stock under a company-wide label is the FALSE_COMFORT failure.`}),c({id:`preferredSupplierId`,entityId:`part`,label:`Preferred Supplier`,type:`STRING`,displayable:!1,reportable:!1,exportable:!1,unsupportedFilterReason:s.NOT_PROJECTED,unsupportedSortReason:s.NOT_PROJECTED,description:`BLOCKED — there is no preferredSupplierId ON the Part. PartSupplierItem{partId, supplierId, preferred} is a separate collection, and collapsing a many-to-many into one column would hide every other supplier.`}),c({id:`version`,entityId:`part`,label:`Version`,type:`NUMBER`,description:`Repository-owned optimistic-concurrency counter, starting at 1. Never caller-supplied.`}),c({id:`createdAt`,entityId:`part`,label:`Created`,type:`TIMESTAMP`,sortable:!0}),c({id:`createdBy`,entityId:`part`,label:`Created By`,type:`STRING`,description:`Actor uid. Repository-owned; every stored Part carries one (readMeta rejects a record missing it).`}),c({id:`updatedAt`,entityId:`part`,label:`Updated`,type:`TIMESTAMP`,sortable:!0}),c({id:`updatedBy`,entityId:`part`,label:`Updated By`,type:`STRING`,description:`Actor uid. Repository-owned; every stored Part carries one.`})],gaps:[o({id:`PART_CATALOGUE_WHOLE_COLLECTION_READ`,title:`Seven surfaces still read the whole parts collection`,entityId:`part`,severity:d.SCALE,finding:"fetchPartMasterList reads all of `parts` with no limit, cursor or criteria, and seven surfaces depend on getting all of it — name resolution, scanner lookup, two part pickers, the warehouse manager catalogue, the Parts catalog list and Part detail.",consequence:`On a real catalogue these are slow. None of them is WRONG, which is why they were left alone.`,refused:`Making the shared reader bounded so the list inherited paging for free. That was tried, and it silently truncated all seven: a scanner that cannot find part 51 reports the part does not exist.`,resolution:`A targeted read per consumer — lookup by part number, a searched picker, a single-document detail read. Tracked in services/partMasterQueries.PART_CATALOGUE_WHOLE_COLLECTION_READ.`}),o({id:`PART_LIST_BALANCE_N1_GAP`,title:`Balance figures require one callable per part`,entityId:`part`,fieldId:`warehouseAvailable`,severity:d.SCALE,reason:s.NOT_PROJECTED,finding:`getPartBalance is a SINGLE-PART callable. There is no batch or list-scoped balance read.`,consequence:`A Warehouse Available or On Order column would issue N callables per page.`,refused:`Rendering the columns anyway and hiding the cost behind a spinner.`,resolution:`A list-scoped balance projection, or an explicitly bounded batch read.`}),o({id:`PART_INVENTORY_VALUATION_AUTHORITY_GAP`,title:`The Part carries no cost or price, so there is no inventory value`,entityId:`part`,fieldId:`unitCost`,severity:d.MISSING_AUTHORITY,reason:s.NO_AUTHORITY,finding:`The canonical Part carries no cost of any kind — not unit, standard, average or latest — and no sell or list price.`,consequence:`There is no inventory value to display and no basis on which one could be computed.`,refused:`Multiplying a quantity by whichever cost happened to exist elsewhere (a supplier item's unitPrice) and calling the result inventory value. That would invent a valuation policy in a list.`,resolution:`Financial Architecture. A valuation basis is a policy decision, not a column.`}),o({id:`PART_BUSINESS_LINE_NOT_AUTHORITATIVE`,title:`A Part has no operating company or business line`,entityId:`part`,fieldId:`businessLine`,severity:d.MISSING_AUTHORITY,reason:s.NO_AUTHORITY,finding:`The Part carries no operating company and no line-of-business field.`,refused:`Inferring Taylor vs Ventana from the manufacturer or from description text. The domain defines no such relationship, and a guess rendered as a filterable column becomes a fact somebody reports on.`}),o({id:`PART_DESCRIPTION_SEARCH_INDEX_GAP`,title:`Description cannot be searched by substring`,entityId:`part`,fieldId:`description`,severity:d.MODELLING,reason:s.NEEDS_INDEX,finding:`Firestore has no substring search, and no search index or projection exists for Part text.`,refused:`Fetching every Part and running .includes() over descriptions in the browser.`,resolution:`Identifier-first search now (part number, manufacturer part number); a search projection later.`}),o({id:`PART_REORDER_POINT_IS_DERIVED`,title:`Reorder point is calculated, not stored`,entityId:`part`,fieldId:`reorderPoint`,severity:d.MODELLING,reason:s.DERIVED_AT_READ,finding:`inventoryAnalyticsService.calculateReorderPoint(usage, leadTimeDays, 1.5) computes it at read.`,consequence:`It can be displayed where the analytics read has run, but never filtered or sorted server-side.`,resolution:`A stored or projected reorder point, if a cross-Part query for it is ever really needed.`}),o({id:`PART_SUPPLIER_IS_MANY_TO_MANY`,title:`There is no single preferred supplier on a Part`,entityId:`part`,fieldId:`preferredSupplierId`,severity:d.MODELLING,reason:s.NOT_PROJECTED,finding:`PartSupplierItem{partId, supplierId, …, preferred} is a separate collection.`,refused:`Inventing a single Vendor column on the Part, which would hide every other supplier.`}),o({id:`PART_LIST_FILTER_INDEX_GAP`,title:`Only status and stocking class are index-backed filters`,entityId:`part`,severity:d.MODELLING,reason:s.NEEDS_INDEX,finding:`The Part list offers filters on status and stockingClass. The retired pilot list also offered part number, tracking, unit and category — none of which had a declared composite index, so each would have failed at read time with an index-required error while CI stayed green.`,consequence:`Narrowing by tracking type or unit is not available on the list today.`,refused:`Keeping the four unverified filters. An offered filter that errors is worse than an absent one.`,resolution:`Declare the composite indexes each additional filter combination needs — noting that optional filters multiply: two already demand three composites, and each further one grows that set.`}),o({id:`INVENTORY_HEALTH_QUERY_PROJECTION_GAP`,title:`Inventory Health cannot be paged, filtered or sorted at the query`,entityId:`part`,severity:d.SCALE,reason:s.DERIVED_AT_READ,finding:"Health is NETTED from the append-only inventory_transactions ledger: the client reads the whole collection unbounded, sums it per part, and classifies. Two things follow. (1) A netted total over a truncated input is not partial, it is WRONG presented as complete — a page holding a receipt but not the reservation against it reports 16 available where the truth is 4. (2) The ledger has NO total-order field spanning every document: LEGACY entries carry `timestamp`, OPERATIONAL entries carry `recordedAt`, no entry carries both, and Firestore's orderBy silently EXCLUDES documents missing the ordered field — so any cursor order over it deletes an entire era of live entries with no error.",consequence:`Filtering or sorting the list BY health, and whole-population health counts, are all unavailable at scale. The health queue is correct today only because the read is unbounded.`,refused:`Capping the ledger read to make the list page. That trades a slow honest number for a fast false one, and overstatement is the dangerous direction: it sends somebody to a shelf emptier than the screen claims.`,resolution:`A trusted server-side health projection, maintained by the ledger's own writers, defining source facts, freshness, UNKNOWN, the onOrder and mobile/company splits, and its update authority. That is a backend package with its own contract, not something a list migration can bolt on.`}),o({id:`PART_CATALOGUE_RECONCILIATION_CANNOT_BE_PAGED`,title:`The /inventory catalogue is a reconciliation, not a list`,entityId:`part`,severity:d.MODELLING,finding:"composeGovernedPartsWorkspace reconciles the canonical `parts` read against the static catalog and enforces a FULL-ACCOUNTING invariant — every canonical Part resolves to exactly one row — by comparing whole-set counts. An incomplete read BLOCKS the catalogue outright rather than rendering a subset.",consequence:`Cursor paging that read would make canonicalCount the page size, so the invariant would compare 50 against 50 and pass while proving nothing.`,refused:`Paging the composed rows and keeping the invariant's name. A guarantee that silently changes scope is worse than one that is removed, because the screen still claims it.`,resolution:`Decide first whether the static-catalog reconciliation is still required. If it is retired, the catalogue becomes an ordinary list and pages like any other; while it stands, the invariant is the feature and it is whole-set by definition.`}),o({id:`INVENTORY_HEALTH_SUMMARY_AND_GLOBAL_SORT_GAP`,title:`Health cannot be counted, filtered or sorted across the whole population`,entityId:`part`,severity:d.SCALE,reason:s.DERIVED_AT_READ,finding:`Balances are now readable for a PAGE of parts in a bounded, batched trusted read (getPartBalances), which is what a list needs. Health remains DERIVED from those balances at read time, so there is no stored, indexable health value for Firestore to count, filter or order by across every Part.`,consequence:`Whole-population health counts, and global filter or sort BY health, are unavailable. Per-row health and bounded paging are not.`,refused:`Materializing a health field to make it sortable. financeReadProjection.ts states the rule this follows: a possibly-stale stored balance is never trusted, and AR is derived from durable facts on every read. A cached health number is a number somebody will believe after it stops being true — and unlike a slow read, it fails silently.`,resolution:`If whole-population counts are genuinely needed, a materialized projection must first define its update authority, freshness, failure behaviour, replay and repair. That is a decision about accepting staleness in exchange for queryability, not a technical gap to close.`})]}),C=m({id:`part.index`,entityId:`part`,label:`Parts`,surface:`INDEX`,columns:[h({fieldId:`internalPartNumber`,sortable:!0}),h({fieldId:`name`}),h({fieldId:`status`,sortable:!0}),h({fieldId:`stockingClass`}),h({fieldId:`stockingUnit`}),h({fieldId:`controlType`})],filters:[f({fieldId:`status`,operators:[`EQUALS`,`IN`]}),f({fieldId:`stockingClass`,operators:[`EQUALS`,`IN`]})],defaultSort:[p({fieldId:`internalPartNumber`,direction:`ASC`})],pageSize:50,savedViews:[g({id:`recent`,label:`Recently viewed`,kind:`RECENTLY_VIEWED`,isDefault:!0}),g({id:`active`,label:`Active parts`,filters:[{fieldId:`status`,operator:`EQUALS`,value:`ACTIVE`}],sort:[p({fieldId:`internalPartNumber`,direction:`ASC`})]})],rowNavigationTo:`/inventory/:partId`});export{C as n,S as t};